INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (234, 5, 'Quelles sont les conditions de validité du jeûne ?', 'L''intention (Niyyah), l''abstention (manger/boire/sexe), la pureté (femmes), et le moment (Ramadan).', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (238, 5, 'Quelles sont les obligations du wudû ?', 'Intention, laver le visage, les bras (coudes), essuyer la tête, les pieds (chevilles), l''ordre et continuité.', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (179, 6, 'Quel est le premier mois du calendrier islamique ?', 'Muharram', 'qcm', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-10 23:53:27.184077', '2026-02-10 23:53:27.184077');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (184, 6, 'Combien de fois par jour doit-on prier au minimum ?', '5 fois', 'qcm', NULL, NULL, NULL, NULL, 'facile', 25, NULL, true, '2026-02-10 23:53:27.240819', '2026-02-10 23:53:27.240819');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (164, 4, 'Quelle bataille est appelée "la bataille décisive" ?', 'Bataille de Badr', 'qcm', NULL, NULL, NULL, NULL, 'moyen', 15, NULL, true, '2026-02-10 23:53:26.85064', '2026-02-10 23:53:26.85064');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (205, 7, 'Réciter le hadith 1 : Les actes ne valent que par les intentions', 'D''après l''Émir des croyants, Abou Hafs ''Omar ibn al-Khattâb (qu''Allah l''agrée) qui a dit : « J''ai entendu l''Envoyé d''Allah (que la prière et la paix d''Allah soient sur lui) dire : « Certes, les œuvres ne valent que par les intentions et chaque individu sera rétribué en fonction de son intention. Ainsi, quiconque émigre vers Allah et Son Messager, alors son émigration est pour Allah et Son Messager ; et quiconque émigre pour obtenir quelque bien de ce bas monde, ou pour épouser une femme, son émigration ne lui sera comptée que pour ce vers quoi il a émigré. »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (206, 7, 'Réciter le hadith 2 : L''Islam, la foi et l''excellence (Ihsan)', 'D''après ''Omar (qu''Allah l''agrée) : « Un jour, alors que nous étions assis auprès de l''Envoyé d''Allah (que la prière et la paix d''Allah soient sur lui), voici qu''apparut à nous un homme aux vêtements d''une blancheur éclatante et aux cheveux d''une noirceur intense... [Il posa des questions sur l''Islam, la Foi et l''Excellence]... Puis l''homme partit. Le Prophète (que la prière et la paix d''Allah soient sur lui) me demanda : « Ô ''Omar, sais-tu qui m''a interrogé ? » Je répondis : « Allah et Son Messager savent mieux. » Il dit : « C''est Gabriel (Jibril) qui est venu vous enseigner votre religion. »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (233, 5, 'Quelles sont les conditions d’obligation du jeûne ?', 'L''Islam, la puberté, la raison, la santé (capacité), et la résidence (ne pas être en voyage).', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (236, 5, 'Manger par oubli annule-t-il ?', 'Non, le jeûne reste valide selon la majorité des savants (''C''est Allah qui l''a nourri'').', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (237, 5, 'Le vomissement volontaire annule-t-il ?', 'Oui, s''il est provoqué. S''il est involontaire, non.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (285, 8, 'Qui fut le premier Calife ?', 'Abou Bakr As-Siddiq', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 10, 'LISTE 3', false, '2026-02-11 23:41:22.778789', '2026-02-11 23:41:22.778789');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (291, 8, 'Où se trouve la mosquée Al-Aqsa ?', 'Jérusalem (Al-Qods)', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 10, 'LISTE 5', false, '2026-02-11 23:41:22.778789', '2026-02-11 23:41:22.778789');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (207, 7, 'Réciter le hadith 3 : Les piliers de l''Islam', 'D''après Abou Abd er-Rah''man, Abd Allah ibn Omar, ibn l-Khattab (qu''Allah l''agrée) : « J''ai entendu l''Envoyé de Dieu (que la prière et la paix d''Allah soient sur lui) dire : « L''Islam est bâti sur cinq piliers : 1. Le témoignage qu''il n''est d''autre Dieu qu''Allah et que Mohammed est Son Envoyé. 2. L''accomplissement de la prière rituelle. 3. L''acquittement de l''aumône (impôt rituel). 4. Le pèlerinage à la Maison de Dieu. 5. Le Jeûne du mois de Ramadan. »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (208, 7, 'Réciter le hadith 4 : La prédestination de l''homme', 'D''après ''Abdallah ibn Mas''ud (qu''Allah l''agrée) : « L''Envoyé d''Allah (que la prière et la paix d''Allah soient sur lui), le véridique, le digne de foi, nous a dit : « La création de chacun de vous s''accomplit dans le ventre de sa mère en quarante jours, sous forme de goutte de sperme... Ensuite, Allah lui envoie un Ange qui insuffle l''âme en lui et lui ordonne d''écrire quatre choses : sa subsistance, son terme, ses œuvres et s''il sera malheureux ou heureux... »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (209, 7, 'Réciter le hadith 5 : Rejet des innovations en religion', 'D''après la Mère des Croyants, Oumm Abdallah ''Aïcha (qu''Allah l''agrée) : « L''Envoyé de Dieu (que la prière et la paix d''Allah soient sur lui) a dit : « Quiconque apporte à notre religion une nouveauté qui n''en provient pas, celui-là est à repousser. »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (210, 7, 'Réciter le hadith 6 : Le licite et l''illicite sont évidents', 'D''après Abou Abdallah En-Noumân ben Bachîr (qu''Allah l''agrée) : « J''ai entendu l''Envoyé de Dieu (que la prière et la paix d''Allah soient sur lui) dire : « Certes, ce qui est permis est évident, et ce qui est interdit est évident aussi. Mais, entre l''un et l''autre, il y a bien des choses équivoques... Quiconque se préserve des choses équivoques, a certes mis à l''abri sa religion et son honneur... Certes, il y a dans le corps un morceau de chair : s''il est sain, tout le corps est sain... C''est le cœur. »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (211, 7, 'Réciter le hadith 7 : La religion est le bon conseil', 'D''après Abou Rouqayya Tamim ibn Aws Ad-Dari (qu''Allah l''agrée) : « Le Prophète (que la prière et la paix d''Allah soient sur lui) a dit : « La religion est le bon conseil (An-Nasiha). » Nous dîmes : « Pour qui ? » Il répondit : « Pour Allah, pour Son Livre, pour Son Messager, pour les dirigeants des Musulmans et pour l''ensemble des Musulmans. »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (212, 7, 'Réciter le hadith 8 : Le caractère sacré du Musulman', 'D''après Ibn ''Omar (qu''Allah l''agrée) : « L''Envoyé d''Allah (que la prière et la paix d''Allah soient sur lui) a dit : « Il m''a été ordonné de combattre les gens jusqu''à ce qu''ils témoignent qu''il n''y a de divinité digne d''adoration qu''Allah et que Muhammad est Son Messager, qu''ils accomplissent la prière et qu''ils s''acquittent de la zakat. S''ils font cela, ils auront préservé vis-à-vis de moi leur sang et leurs biens... »
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (213, 7, 'Réciter le hadith 9 : La responsabilité et le bon comportement', '« J’ai entendu l’Envoyé de Dieu (que la prière et le salut d’Allah soient sur lui) dire :
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (214, 7, 'Réciter le hadith 10 : Ne sont acceptées que les bonnes choses', 'D''après Abou Hourayra (qu''Allah l''agrée) : « L''Envoyé de Dieu (que la prière et la paix d''Allah soient sur lui) a dit : « Dieu le Très-Haut est bon et n''accepte que ce qui est bon. Sachez que Dieu a ordonné aux croyants ce qu''Il a ordonné aux Envoyés... Puis il parla de l''homme qui fait un long voyage... levant les mains au ciel criant : « Seigneur ! Seigneur ! », alors que sa nourriture est de source illicite... Il est loin pour que son invocation soit exaucée. »
