INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (242, 5, 'Peut-on faire le tayammum en présence d’eau ?', 'Non, sauf si l''eau est inaccessible ou présente un danger réel pour la santé de l''individu.', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (244, 5, 'La prière en groupe est-elle obligatoire ou recommandée ?', 'C''est une Sunna Mouakkada (fortement recommandée) ou une obligation communautaire (Fard Kifaya) selon les avis.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (250, 5, 'L’eau qui change de couleur reste-t-elle pure ?', 'Oui si le changement vient d''un élément pur (terre/feuilles). Non s''il vient d''une impureté (Nadjassa).', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (252, 5, 'Le jeûne est-il valide si l’on oublie le ghusl avant Fajr ?', 'Oui, le jeûne reste valide. On peut commencer le jeûne en état de Janaba et faire le ghusl après l''aube.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, false, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
