INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (554, 8, 'Qui était Imam Mâlik ?', 'Fondateur de l''école malikite, auteur d''Al-Muwatta.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 10, 'LISTE 3', false, '2026-02-12 00:44:36.179314', '2026-02-12 00:44:36.179314');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (251, 5, 'Oublier un pilier invalide-t-il la prière ?', 'Oui, si on ne le rattrape pas immédiatement. Un pilier ne peut être remplacé par une prosternation d''oubli.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (243, 5, 'Quelle est la différence entre pilier (rukn) et obligation (wâjib) ?', 'Le pilier manquant invalide l''acte totalement. L''obligation manquée par oubli peut être compensée par Sujud as-Sahw.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (241, 5, 'Toucher une femme annule-t-il le wudû ?', 'Non, sauf s''il y a désir charnel ou contact direct voluptueux (selon les écoles Maliki/Shafi''i).', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (240, 5, 'Quand le ghusl devient-il obligatoire ?', 'Rapport sexuel, éjaculation, fin des règles (menstrues), fin des lochies, et le décès.', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (248, 5, 'L’injection non nutritive annule-t-elle ?', 'Non, les injections intramusculaires ou intraveineuses non nutritives n''annulent pas le jeûne.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (239, 5, 'Quelles sont les choses qui annulent le wudû ?', 'Sortie de gaz/urine/excréments, sommeil profond, perte de conscience, toucher de parties intimes directement.', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (245, 5, 'Si on doute entre 3 et 4 rak‘ât, que fait-on ?', 'On se base sur le nombre le plus petit (3), on termine la prière et on effectue la prosternation de l''oubli.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (247, 5, 'Peut-on prier en chaussures ?', 'Oui, à condition qu''elles soient parfaitement pures (tahir). Le Prophète (ﷺ) a prié avec ses chaussures.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (246, 5, 'Rire pendant la prière annule-t-il ?', 'Oui, le rire aux éclats annule la prière (et parfois les ablutions selon l''école Hanafi).', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (249, 5, 'L’intention est-elle obligatoire pour le wudû ?', 'Oui, selon la majorité des écoles (Maliki, Shafi''i, Hanbali), car c''est un acte d''adoration.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:37:00.650526', '2026-02-11 23:37:00.650526');
