INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (574, 6, 'Comment appelle-t-on les habitants de Daloa ?', 'Les Daloais', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-12 00:59:12.082539', '2026-02-12 00:59:12.082539');
