INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (570, 6, 'Comment appelle-t-on les habitants de San-Pédro ?', 'Les San-Pédrois', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-12 00:59:12.082539', '2026-02-12 00:59:12.082539');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (325, 5, 'Peut-on essuyer sur ses chaussettes (Mash) pendant les ablutions ?', 'Oui, sous certaines conditions (les avoir mises en état de pureté).', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:49:03.520584', '2026-02-11 23:49:03.520584');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (320, 5, 'Que faire si on oublie le premier Tashahhud dans une prière de 4 Rak''at ?', 'Continuer sa prière et effectuer deux prosternations de l''oubli (Sujud as-Sahw) avant le Salam.', 'texte_libre', NULL, NULL, NULL, NULL, 'difficile', 25, NULL, true, '2026-02-11 23:49:03.520584', '2026-02-11 23:49:03.520584');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (316, 5, 'Qu''est-ce que le ''Tayammum'' ?', 'Ablution à sec avec de la terre ou du sable pur en l''absence d''eau.', 'texte_libre', NULL, NULL, NULL, NULL, 'moyen', 25, NULL, true, '2026-02-11 23:49:03.520584', '2026-02-11 23:49:03.520584');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (337, 4, 'Dans quelle ville et en quelle année est né le Prophète ﷺ ?', 'À La Mecque, en l''an 570 (L''année de l''Éléphant).', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (338, 4, 'Qui était la nourrice (mère de lait) du Prophète ﷺ ?', 'Halima Sa''diya.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (339, 4, 'Qui a pris soin du Prophète ﷺ après la mort de sa mère et de son grand-père ?', 'Son oncle Abou Talib.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (340, 4, 'Comment appelait-on le Prophète ﷺ avant la révélation pour son honnêteté ?', 'Al-Amin (Le digne de confiance).', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (341, 4, 'À quel âge le Prophète ﷺ a-t-il reçu la première révélation ?', 'À 40 ans.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (342, 4, 'Dans quelle grotte le Prophète ﷺ a-t-il reçu les premiers versets ?', 'La grotte de Hira (Djebel an-Nour).', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (343, 4, 'Quel est le premier mot révélé au Prophète ﷺ par l''ange Jibril ?', 'Iqra (Lis !).', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (344, 4, 'Qui était la première femme à embrasser l''Islam ?', 'Khadija bint Khuwaylid.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (345, 4, 'Qui était le premier homme (adulte) à embrasser l''Islam ?', 'Abou Bakr As-Siddiq.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
