INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (358, 4, 'En quelle année et à quel âge est décédé le Prophète ﷺ ?', 'En l''an 11 de l''Hégire, à l''âge de 63 ans.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
