INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (363, 4, 'Quel était le nom de la chamelle du Prophète ﷺ ?', 'Al-Qaswa.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
