INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (368, 4, 'Quel compagnon le Prophète ﷺ a-t-il envoyé comme premier ambassadeur à Médine ?', 'Mous''ab ibn ''Omayr.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (370, 4, 'Quelles sont les deux tribus de Médine que le Prophète ﷺ a réconciliées ?', 'Les Aws et les Khazraj.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, false, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
