INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (371, 4, 'Quel était le nom du grand-père du Prophète ﷺ qui l''a nommé Muhammad ?', 'Abdul-Muttalib.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, true, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
