INSERT INTO public.questions (id, rubrique_id, question_texte, reponse_correcte, type, choix_a, choix_b, choix_c, choix_d, difficulte, points, reference, utilise, created_at, updated_at) VALUES (369, 4, 'Pendant combien d''années le Prophète ﷺ a-t-il prêché secrètement à La Mecque ?', '3 ans.', 'texte_libre', NULL, NULL, NULL, NULL, 'facile', 15, NULL, true, '2026-02-12 00:04:39.157561', '2026-02-12 00:04:39.157561');
