INSERT INTO public.evaluations (id, soumission_id, jure_id, equipe_id, manche_id, rubrique_id, note_voix, note_tajwid, note_prononciation, note_totale, criteres_notes, commentaire, statut, date_evaluation, session_id) VALUES (82, NULL, 4, 16, 43, 7, NULL, NULL, NULL, 20.00, '{"questions": [{"correct": true, "answered": true, "question": {"id": 207, "type": "texte_libre", "points": 20, "choix_a": null, "choix_b": null, "choix_c": null, "choix_d": null, "utilise": false, "reference": null, "created_at": "2026-02-11T01:09:28.072Z", "difficulte": "moyen", "updated_at": "2026-02-11T01:09:28.072Z", "rubrique_id": 7, "question_texte": "Réciter le hadith 3 : Les piliers de l''Islam", "reponse_correcte": "D''après Abou Abd er-Rah''man, Abd Allah ibn Omar, ibn l-Khattab (qu''Allah l''agrée) : « J''ai entendu l''Envoyé de Dieu (que la prière et la paix d''Allah soient sur lui) dire : « L''Islam est bâti sur cinq piliers : 1. Le témoignage qu''il n''est d''autre Dieu qu''Allah et que Mohammed est Son Envoyé. 2. L''accomplissement de la prière rituelle. 3. L''acquittement de l''aumône (impôt rituel). 4. Le pèlerinage à la Maison de Dieu. 5. Le Jeûne du mois de Ramadan. »\n\nSource : Rapporté par Al-Bukhari et Muslim."}}], "correctCount": 1, "incorrectCount": 0}', '', 'valide', '2026-02-13 01:57:29.198951', 177);
INSERT INTO public.evaluations (id, soumission_id, jure_id, equipe_id, manche_id, rubrique_id, note_voix, note_tajwid, note_prononciation, note_totale, criteres_notes, commentaire, statut, date_evaluation, session_id) VALUES (83, NULL, 4, 15, 43, 7, NULL, NULL, NULL, 20.00, '{"questions": [{"correct": true, "answered": true, "question": {"id": 214, "type": "texte_libre", "points": 20, "choix_a": null, "choix_b": null, "choix_c": null, "choix_d": null, "utilise": false, "reference": null, "created_at": "2026-02-11T01:09:28.152Z", "difficulte": "moyen", "updated_at": "2026-02-11T01:09:28.152Z", "rubrique_id": 7, "question_texte": "Réciter le hadith 10 : Ne sont acceptées que les bonnes choses", "reponse_correcte": "D''après Abou Hourayra (qu''Allah l''agrée) : « L''Envoyé de Dieu (que la prière et la paix d''Allah soient sur lui) a dit : « Dieu le Très-Haut est bon et n''accepte que ce qui est bon. Sachez que Dieu a ordonné aux croyants ce qu''Il a ordonné aux Envoyés... Puis il parla de l''homme qui fait un long voyage... levant les mains au ciel criant : « Seigneur ! Seigneur ! », alors que sa nourriture est de source illicite... Il est loin pour que son invocation soit exaucée. »\n\nSource : Rapporté par Muslim."}}], "correctCount": 1, "incorrectCount": 0}', '', 'valide', '2026-02-13 01:57:49.316558', 177);
INSERT INTO public.evaluations (id, soumission_id, jure_id, equipe_id, manche_id, rubrique_id, note_voix, note_tajwid, note_prononciation, note_totale, criteres_notes, commentaire, statut, date_evaluation, session_id) VALUES (84, NULL, 4, 14, 43, 7, NULL, NULL, NULL, 0.00, '{"questions": [{"correct": false, "answered": true, "question": {"id": 206, "type": "texte_libre", "points": 20, "choix_a": null, "choix_b": null, "choix_c": null, "choix_d": null, "utilise": false, "reference": null, "created_at": "2026-02-11T01:09:28.063Z", "difficulte": "moyen", "updated_at": "2026-02-11T01:09:28.063Z", "rubrique_id": 7, "question_texte": "Réciter le hadith 2 : L''Islam, la foi et l''excellence (Ihsan)", "reponse_correcte": "D''après ''Omar (qu''Allah l''agrée) : « Un jour, alors que nous étions assis auprès de l''Envoyé d''Allah (que la prière et la paix d''Allah soient sur lui), voici qu''apparut à nous un homme aux vêtements d''une blancheur éclatante et aux cheveux d''une noirceur intense... [Il posa des questions sur l''Islam, la Foi et l''Excellence]... Puis l''homme partit. Le Prophète (que la prière et la paix d''Allah soient sur lui) me demanda : « Ô ''Omar, sais-tu qui m''a interrogé ? » Je répondis : « Allah et Son Messager savent mieux. » Il dit : « C''est Gabriel (Jibril) qui est venu vous enseigner votre religion. »\n\nSource : Rapporté par Muslim."}}], "correctCount": 0, "incorrectCount": 1}', '', 'valide', '2026-02-13 01:57:56.848377', 177);
